const execution = $json.execution;
const lastNode = execution?.lastNodeExecuted;
const errorMessage = execution?.error?.message || 'Workflow execution failed';

// Attempt to retrieve runId from execution data context
let runId = 'unknown';
try {
  const data = execution?.data?.resultData?.runData;
  for (const nodeName in data) {
    const nodeRuns = data[nodeName];
    if (Array.isArray(nodeRuns) && nodeRuns.length > 0) {
      const firstRun = nodeRuns[0];
      const json = firstRun?.data?.main?.[0]?.[0]?.json;
      if (json?.body?.runId) {
        runId = json.body.runId;
        break;
      }
      if (json?.data?.runId) {
        runId = json.data.runId;
        break;
      }
    }
  }
} catch (e) {}

return {
  runId,
  errorCode: 'WORKFLOW_FAILED',
  errorMessage: `[Node: ${lastNode}] ${errorMessage}`,
  timestamp: new Date().toISOString()
};
